templates.checkin:
{{$meet := .Meet}}
{{range .Sheets}}
<section class="sheet{{if .Break}} break{{end}}">
  <h2>{{.Event}} {{.Round}} {{.Heat}}</h2>
  <p>计划时间 {{.Time}}{{if $.ShowCheckIn}}，检录时间 {{.CheckIn}}{{end}}</p>
  <table class="grid">
    <thead><tr><th class="num">{{.PositionLabel}}</th><th>{{.NameLabel}}</th><th class="org">单位</th><th class="check">到</th></tr></thead>
    <tbody>
      {{range .Lines}}<tr><td class="num">{{.Position}}</td><td>{{.Name}}</td><td class="org">{{.Unit}}</td><td class="check"><span class="box"></span></td></tr>
      {{end}}
    </tbody>
  </table>
</section>
{{end}}
{{with .Slots.after_events}}{{.}}{{end}}
